from cocotb.triggers import Timer


def _get_assembler():
    for module_name in ("rvgen", "rvgen.assembler", "riscv_assembler"):
        try:
            module = importlib.import_module(module_name)
        except ImportError:
            continue
        assembler = getattr(module, "assemble_rv32im", None)
        if assembler is not None:
            return assembler
    raise ImportError("Could not find assemble_rv32im")


def _instruction_word(assembled):
    if isinstance(assembled, int):
        return assembled
    if isinstance(assembled, bytes):
        return int.from_bytes(assembled[:4], byteorder="little")
    if isinstance(assembled, str):
        return int(assembled, 0)
    if isinstance(assembled, (list, tuple)):
        return _instruction_word(assembled[0])
    raise TypeError(f"Unsupported assemble_rv32im output: {type(assembled).__name__}")


@cocotb.test()
async def supported_add_deasserts_branch_taken(dut):
    instruction = _instruction_word(_get_assembler()("add x3, x1, x2"))

    dut.opcode.value = (instruction >> 0) & 0x7F
    dut.funct3.value = (instruction >> 12) & 0x7
    dut.funct7.value = (instruction >> 25) & 0x7F
    dut.operand_a.value = 0x00000012
    dut.operand_b.value = 0x00000034

    await Timer(1, unit="ns")

    observed = int(dut.branch_taken.value)
    assert observed == 0, f"expected branch_taken 0x0, observed 0x{observed:X}"
